from collections import Counter
from math import log2
from random import Random
from vs import corpus, ivtff, path
P={0:['q','d','s','t','k','p','f','c'],1:['ch','sh','ck','cth','cph'],2:['ok','ot','ol','or'],3:['k2','t2','p2','f2','d2','s2'],4:['ch2','sh2','ckh','cth2','cfh']}
S={1:['dy','dl','dm','ds','dar','dal'],2:['iin','in','ir','iir','iiir'],3:['al','am','an','ar','ain','aiin'],4:['ey','ed','es','edy','eey','eedy'],5:['ly','ry','ny','my','ldy']}
ivtff.SEGMENTATIONS['paper']=sorted(set(['o','a']+sum(P.values(),[])+sum(S.values(),[])))
train,ev=corpus.split_pages('practice'); ids_train={p.id for p in train}; ids_eval={p.id for p in ev}
files={'zl':'ZL3b-n.txt','it':'IT2a-n.txt','rf':'RF1b-e.txt'}
def get(trans,mode):
 pgs=ivtff.parse(path('data','raw',files[trans]),uncertain_space=mode)
 return {l.id:(p.id,l.words) for p in pgs for l in p.lines if l.unit=='P'}
sets={t:{m:get(t,m) for m in ('split','join')} for t in files}
common=set.intersection(*(set(d) for d in (sets[t][m] for t in files for m in ('split','join'))))
def usable(w):return w.isalpha() and not ivtff.uncertain(w) and len(w)>1
def runs(data,ids):
 out=[]
 for lid in sorted(common):
  page,ws=data[lid]
  if page not in ids: continue
  run=[]
  for w in ws:
   if usable(w): run.append(ivtff.segment(w,'paper'))
   else:
    if run:out.append(run);run=[]
  if run:out.append(run)
 return out
def fit(rs):
 s,e=Counter(),Counter()
 for r in rs:
  for w in r:s[w[0]]+=1;e[w[-1]]+=1
 return {g:('start' if s[g]>2*e[g] else 'end' if e[g]>2*s[g] else 'ambig') for g in set(s)|set(e)}
def mi(p):
 n=sum(p.values()); a,b=Counter(),Counter()
 for (x,y),c in p.items():a[x]+=c;b[y]+=c
 return sum(c/n*log2(c*n/(a[x]*b[y])) for (x,y),c in p.items())
def pairs(rs):return Counter((a[-1],b[0]) for r in rs for a,b in zip(r,r[1:]))
def score(rs,cls):
 p=pairs(rs); n=sum(p.values()); q=sum(c for (a,b),c in p.items() if cls.get(a)=='end' and cls.get(b)=='start'); unk=sum(c for (a,b),c in p.items() if a not in cls or b not in cls)
 rng=Random(2711); m=[]
 for _ in range(100):
  perm=[]
  for r in rs:
   x=list(r);rng.shuffle(x);perm.append(x)
  m.append(mi(pairs(perm)))
 return {'tokens':sum(map(len,rs)),'pairs':n,'unknown_pair_fraction':round(unk/n,5),'end_start':round(q/n,5),'mi':round(mi(p),5),'shuffle_mi_mean':round(sum(m)/len(m),5)}
cls=fit(runs(sets['zl']['split'],ids_train))
print('classes ZL training',Counter(cls.values()),'common lines',len(common),'paper units',len(ivtff.SEGMENTATIONS['paper']))
for t in files:
 for m in ('split','join'):print(t,m,score(runs(sets[t][m],ids_eval),cls))
